    public static void create_Pokemon(Player p, int id) throws IOException {
        for (int i1 = 0; i1 < p.map.players.size(); i1++) {
            Player p1 = p.map.players.get(i1);
            int i0 = 121;
            List<Poke_huyen_thoai> list_init = new ArrayList<>();
            for (int i = 0; i < Poke_huyen_thoai.ENTRYS.size(); i++) {
                Poke_huyen_thoai temp = Poke_huyen_thoai.ENTRYS.get(i);
                if (i0 == temp.mob.mob_template.mob_id
                        && temp.mob.map.template.id == p1.map.template.id
                        && p.id == p1.id) {
                    list_init.add(temp);
                }
            }
            //
            if (list_init.size() > 0) {
                int zoneid = p1.map.zone_id;
                if (zoneid == p1.map.zone_id) {
                    zoneid = zoneid - 1;
                }
                if (zoneid == -1) {
                    zoneid = 0;
                    Service.send_box_ThongBao_OK(p, "Pokemon đã xuất hiện ở khu 2");
                }
                Poke_huyen_thoai temp = list_init.get(zoneid);
                if (temp.mob.isdie) {
                    temp.mob.isdie = false;
                    temp.mob.hp = temp.mob.hp_max;
                    temp.mob.id_target = -1;
                    temp.levelBoss = 1;
                    temp.mob.index = temp.index_mob_save;
                    temp.mob.x = p1.x;
                    temp.mob.y = p1.y;
                    try {
                        BOSS_AREA[i0 - 121] = temp.mob.map.zone_id;
                        temp.mob.map.can_PK = false;
                        Message m_local = new Message(1);
                        m_local.writer().writeByte(1);
                        m_local.writer().writeShort(temp.mob.index);
                        m_local.writer().writeShort(temp.mob.x);
                        m_local.writer().writeShort(temp.mob.y);
                        for (int j = 0; j < temp.mob.map.players.size(); j++) {
                            Player p0 = temp.mob.map.players.get(j);
                            p0.conn.addmsg(m_local);
                        }
                        m_local.cleanup();
                    } catch (IOException e) {
                    }
                    BOSS_LIVE[i0 - 121] = 1;
                }else if (!temp.mob.isdie) {
                    Service.send_box_ThongBao_OK(p, "Trong khu đã có pokemon rồi");
                }else{
                    Service.send_box_ThongBao_OK(p, ""
                            + "Có lỗi xảy ra vui lòng báo cho admin.");
                }
            }
        }
        //réult
        Boss.result_boss();
    }

    public static Mob get_mob(Player p, int id) {
        for (int i = 0; i < Poke_huyen_thoai.ENTRYS.size(); i++) {
            Poke_huyen_thoai tempB = Poke_huyen_thoai.ENTRYS.get(i);
            if (!tempB.mob.isdie && tempB.mob.map.template.id == p.map.template.id
                    && tempB.mob.index == id) {
                Mob temp_mob = tempB.mob;
                if (!temp_mob.isdie) {
                    return temp_mob;
                }
            }
        }
        return null;
    }

